import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百一十三章 如何达到天界中的境界","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/113第一百一十三章 如何达到天界中的境界.md","filePath":"meditation/巴利文大藏经/113第一百一十三章 如何达到天界中的境界.md"}'),o={name:"meditation/巴利文大藏经/113第一百一十三章 如何达到天界中的境界.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第一百一十三章-如何达到天界中的境界" tabindex="-1">第一百一十三章 如何达到天界中的境界 <a class="header-anchor" href="#第一百一十三章-如何达到天界中的境界" aria-label="Permalink to &quot;第一百一十三章 如何达到天界中的境界&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>2.第二品</p><p>相应部14相应11经/七界经(界相应/因缘于篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，世间有七界，是哪七界呢？光界、净界、空无边处界、识无边处界、无所有处界、非想非非想处界、想受灭界。弟子们，这就是世间的七界。</p><p>佛陀说七界的时候，有一位听法的出家弟子就对佛陀说：“世尊，光界、净界、空无边处界、识无边处界、无所有处界、非想非非想处界、想受灭界这七界我们如何才能知道它们在什么地方呢？我们如何才能知道它们确实是存在的呢？”</p><p>佛陀说：“弟子们，光界通过黑暗就可以知道它的存在，也就说有光线的地方就是光界，没有光线就看不见世间的事物，那就是黑暗。</p><p>净界通过污秽、不干净的事物，通过内心的胡思乱想就知道它的存在，也就是说没有污秽事物，没有不干净事物的地方就是净界，内心不胡思乱想，保持清净就是净界。</p><p>空无边处界通过物质事物，通过有形的物质世界就可以知道它的存在，也就是说没有物质事物的地方就是虚空，虚空无边无界，这个无边无界的虚空就是空无边处界。</p><p>识无边处界通过无边无界的虚空，通过空无边处界就可以知道它的存在，也就是说明白了虚空是无边无界的之后，就能进一步明白自己的念想、认识、分别、判断也如同虚空一样是无边无界、永无止境的，这就是识无边处界。</p><p>无所有处界通过识无边处界就可以知道它的存在，也就是认为无边无界的虚空是不存在的，是虚假不真实的；认为自己无边无界、永无止境的念想、认识、分别、判断也是不存在的，也是虚假不真实的。内心认为无边无界的虚空，认为自己无边无界、永无止境的念想、认识、分别、判断全部都是不存在的，这就是无所有处界。</p><p>非想非非想处界通过无所有处界就可以知道它的存在，也就是当明白了无边无界的虚空，自己无边无界、永无止境的念想、认识、分别、判断全部都是不存在的，就不会再在内心中生起任何的念想，虽然如此，可是内心中偶尔也会闪出一些微小的杂念，这些杂念非常的微小，就如同大海海面上漂浮着一滴菜油一样，已经可以忽略不计了。内心除了偶尔出现的极微小的杂念外，已经不会再生起任何的念想，这就是非想非非想处界。</p><p>想受灭界通过因缘条件的灭尽就可以知道它的存在，也就是灭尽了「无明」、「行」、「识」、「名色」、「六处」、「触」、「受」、「爱」、「取」、「有」、「生」、「老死」（无明、行、识、名色、六处、触、受、爱、取、有、生、老死解释，见第四十八章、第四十九章）就不会产生任何的感受、念想，连最微细的杂念都不会产生。无念想、无感受、无微细的杂念就不会有任何的烦恼和痛苦，这就是想受灭界。</p><p>这位出家弟子继续问佛陀：“世尊，我已经知道光界、净界、空无边处界、识无边处界、无所有处界、非想非非想处界这六界是天界中的境界，这六界的层次逐渐的升高，尤其是空无边处界、识无边处界、无所有处界、非想非非想处界这四界是最高层次天界中的四种境界，非想非非想处界是最高阶层天界中的境界。而想受灭界其实就是不生不灭涅槃的境界。</p><p>世尊，我现在已经知道它们的法义是什么了，我如何才能证悟达到光界、净界、空无边处界、识无边处界、无所有处界、非想非非想处界这些层层升高的天界境界呢？我如何才能证悟达到想受灭界中不生不灭涅槃的境界呢？”</p><p>佛陀说：“光界、净界、空无边处界、识无边处界、无所有处界、非想非非想处界通过经常的观想它们的法义就能证悟这些天界中的境界。如何观想呢？黑暗没有光线的时候，就观想有光线能够看见世间事物的境界，能够看见世间事物的时候，就观想黑暗没有光线时的情景，这样经常的观想，一旦有光线能够看见世间事物的时候，就知道自己已经在光界之中，光界中的境界也是如此。</p><p>看见污秽、不干净事物的时候，就观想洁净、干净的事物。内心胡思乱想的时候，就观想内心清净时候的境界。这样经常的观想，一旦看见洁净、干净的事物，一旦内心保持清净的时候，就知道自己已经在净界之中，净界中的境界也是如此。</p><p>看见物质事物，看见有形的物质世界就要观想还有无边无界虚空的存在，这样经常的观想，一旦想到无边无界虚空存在的时候，自己已经在空无边处界之中，空无边处界的境界也是如此。</p><p>当内心想到无边无界虚空的时候就要观想自己的念想、认识、分别、判断也如同虚空一样是无边无界、永无止境的，这样经常的观想，一旦想到自己的念想、认识、分别、判断是无边无界、永无止境的时候，自己已经在识无边处界之中，识无边处界的境界也是如此。</p><p>当内心想到无边无界虚空，想到自己的念想、认识、分别、判断是无边无界、永无止境的时候，就要观想无边无界的虚空，自己无边无界、永无止境的念想、认识、分别、判断全部都是虚假不真实的，全部都是不存在的。这样经常的观想，一旦想到无边无界虚空，想到自己无边无界、永无止境的念想、认识、分别、判断全部都是不存在的时候，自己已经在无所有处界之中。无所有处界的境界也是如此。</p><p>当内心想到无边无界虚空，想到自己无边无界、永无止境的念想、认识、分别、判断全部都是不存在的，就要观想既然这些全部都是不存在的，那么就不应该去想任何的事情，虽然这样的观想，可是内心偶尔还是会出现微小的杂念。这样经常的去观想，一旦不去想任何的事情，内心只是偶尔会出现一些微细杂念的时候，自己就已经在非想非非想处界之中，非想非非想处界的境界也是如此。</p><p>弟子们，这样通过观想六界的法义就能证悟达到这些天界中的境界。非想非非想处界还可以这样简单的观想：当内心除了偶尔生起的一些无关紧要的微小杂念外，没有任何的念想生起，通过内心闪现出来的这些残留的微小杂念，就能知道自己已经在非想非非想处界之中。</p><p>弟子们，要证悟达到想受灭界的境界，就要灭尽一切的因缘条件，就要去修习缘起法（缘起法解释，见第四十八章、第四十九章）。</p><p>「无明」完全褪去、消除、灭尽的时候，「行」就灭除了。「行」灭尽了，「识」就灭除了。「识」灭尽了，「名色」就灭除了。「名色」灭尽了，「六处」就灭除了。「六处」灭尽了，「触」就灭除了。「触」灭尽了，「受」就灭除了。「受」灭尽了，「爱」就灭除了。「爱」灭尽了，「取」就灭除了。「取」灭尽了，「有」就灭除了。「有」灭尽了，「生」就灭除了。「生」灭尽了，忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡就灭除了。这就是世间人或众生痛苦和烦恼灭除、灭尽的过程。世间的人或众生按缘起法（缘起法解释，见第四十八章、第四十九章）的逆行就能从生死轮回的烦恼和痛苦中解脱出来，这样去修行就能证悟达到想受灭界中不生不灭涅槃的境界。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',25)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
